urlset:
{% for endpoint in ['publico.inicio', 'publico.articulos', 'publico.artefactos', 'publico.documentos', 'publico.sobre_mi'] %}
{{ url_for(endpoint, _external=true) }}
{% endfor %}
{% for a in articulos %}{{ url_for('publico.articulo', slug=a.slug, _external=true) }}{{ a.actualizado.date().isoformat() }}
{% endfor %}
{% for a in artefactos %}{{ url_for('publico.artefacto', slug=a.slug, _external=true) }}{{ a.actualizado.date().isoformat() }}
{% endfor %}
{% for d in documentos %}{{ url_for('publico.documento', slug=d.slug, _external=true) }}{{ d.actualizado.date().isoformat() }}
{% endfor %}
